math and plan-reading evidence; have the teacher check your practical work."}, "teachingTool": {"kind": "case-board", "version": 1, "frames": [{"title": "E · Example community room — coordinate the views", "image": "/trades-etf/building.svg", "alt": "E · Example community room — coordinate the views. Compare drawing E with a teacher change: plan says a door begins 2 ft from the corner; a proposed elevation says 3 ft. Flag the conflicting datum/offset before building.", "prompt": "A model door must move 1 ft 6 in at scale 1/2 in = 1 ft. Calculate model movement and list the drawing views that need checking.", "body": "Read written dimensions; this screen drawing is not to scale. Keep the supplied plan beside your physical work."}]}}, {"id": "mvp-etf-2-10-evidence", "type": "exit_ticket", "capture": true, "requiredForCompletion": true, "prompt": "A model door must move 1 ft 6 in at scale 1/2 in = 1 ft. Calculate model movement and list the drawing views that need checking. Include units, enough working to check, and your notebook page/date. Practical evidence is checked with your teacher.", "targetId": "etf26.p2.math", "evidenceRole": "exit", "xp": 10, "workshop": {"taskLabel": "Save your individual evidence", "purpose": "One short response connects your calculation and plan interpretation to the notebook. The teacher observes measuring and building separately."}, "sei": {"visualBlockId": "mvp-etf-2-10-explain", "frames": [{"level": 1, "text": "The plan shows ___. I used ___ to calculate ___. My answer is ___ (units). My notebook page is ___."}, {"level": 2, "text": "My reference is ___. I checked ___ by ___. The test supports ___, with the limit ___."}], "wordBank": ["dimension", "datum", "units", "calculate", "inspect", "revision"], "talkFirst": false}}]}}]$etf_data$::jsonb; begin if (select count(*) from jsonb_array_elements(expected) j join lessons l on l.id=(j->>'id')::uuid where to_jsonb(l) @> j) <> 10 then raise exception 'Stored lesson content does not match authored source'; end if; end $check$;
do $vocab$ declare data jsonb := $etf_data$[{"lesson_id": "7423bc8c-233c-5a33-bdfc-7dd34e537801", "lesson_slug": "mvp-etf-2-01", "name": "ETF P2 · 01 · Build a Tower and Learn from Its Failure", "unit_id": "trades-etf-2", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p2.vocabulary", "terms": [{"term": "load", "tier": 3, "category": "structures", "definition": "An external force acting on a structure or part, such as the weight of an object placed on it.", "example": "Identical erasers apply loads through their weight; an eraser count is not a measured force in newtons.", "order_index": 0, "difficulty": "medium"}, {"term": "footprint", "tier": 3, "category": "layout", "definition": "The area or outline an object occupies when viewed from above.", "example": "A 4 × 2 ft desk has a 2 × 1 in paper footprint at the chosen scale.", "order_index": 1, "difficulty": "medium"}, {"term": "elevation view", "tier": 3, "category": "drawing", "definition": "A drawing looking straight at a vertical face, showing heights and vertical relationships.", "example": "Show the selected divider height in a view of its vertical face.", "order_index": 2, "difficulty": "medium"}, {"term": "capacity", "tier": 3, "category": "structures", "definition": "The greatest load or demand that meets a stated performance limit under specified conditions.", "example": "Record the count at the agreed test limit for each beam; state the limit used.", "order_index": 3, "difficulty": "medium"}, {"term": "baseline", "tier": 2, "category": "investigation", "definition": "The original or reference result used for comparison with a changed design or condition.", "example": "Use the original wrap's result as the comparison point for the revised design.", "order_index": 4, "difficulty": "medium"}, {"term": "percent increase", "tier": 2, "category": "math", "definition": "The increase divided by the original value, multiplied by 100%.", "example": "A 15% increase on a fictional $80 estimate adds $12 and gives a revised total of $92.", "order_index": 5, "difficulty": "medium"}, {"term": "trial", "tier": 2, "category": "investigation", "definition": "One run of a test using a recorded set of conditions.", "example": "Record each run and identify whether it used a fresh specimen or a previously loaded one.", "order_index": 6, "difficulty": "medium"}, {"term": "revision", "tier": 2, "category": "communication", "definition": "An identified change to a drawing, plan, or product that replaces an earlier version.", "example": "After checking an unclear endpoint, date the drawing and label the corrected version revision B.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "fdb04055-26be-5e28-95ba-767db31acfac", "lesson_slug": "mvp-etf-2-02", "name": "ETF P2 · 02 · Find a Shape That Resists Bending", "unit_id": "trades-etf-2", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p2.vocabulary", "terms": [{"term": "span", "tier": 3, "category": "structures", "definition": "The distance between supports, with the measurement endpoints stated as faces or centerlines.", "example": "Change the stated distance between the beam supports while keeping the beam shape the same.", "order_index": 0, "difficulty": "medium"}, {"term": "beam", "tier": 3, "category": "structures", "definition": "A structural member that carries loads across a span mainly by resisting bending.", "example": "The paper member bridges two supports and carries the small test objects.", "order_index": 1, "difficulty": "medium"}, {"term": "cross section", "tier": 3, "category": "drawing", "definition": "The shape exposed by an imaginary cut across an object, such as the end shape of a folded beam.", "example": "Compare the flat paper's end shape with the folded beam's end shape.", "order_index": 2, "difficulty": "medium"}, {"term": "deflection", "tier": 3, "category": "structures", "definition": "The change in a part's position caused by loading, measured from its unloaded position.", "example": "A midspan height changing from 2 in to 1 3/4 in gives 1/4 in of downward deflection.", "order_index": 3, "difficulty": "medium"}, {"term": "stiffness", "tier": 3, "category": "structures", "definition": "How strongly a structure resists deformation under load; it is different from the load it can withstand before failure.", "example": "Compare bending under the same load to investigate how the fold changes resistance to deformation.", "order_index": 4, "difficulty": "medium"}, {"term": "support", "tier": 3, "category": "structures", "definition": "A part or contact that holds a structure and transfers forces from it to another part or surface.", "example": "Keep the two supporting surfaces in the same positions for both beam shapes.", "order_index": 5, "difficulty": "medium"}, {"term": "controlled variable", "tier": 2, "category": "investigation", "definition": "A condition deliberately kept the same to make a comparison fair.", "example": "Use the same paper allowance, support spacing, and loading method when comparing shapes.", "order_index": 6, "difficulty": "medium"}, {"term": "compression", "tier": 3, "category": "structures", "definition": "A loading action that pushes parts of a material toward one another.", "example": "The support foot pushes into the pad and compresses it.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "8c8c7873-a69e-50ba-81bd-1c3b6a05300a", "lesson_slug": "mvp-etf-2-03", "name": "ETF P2 · 03 · Survey a Space and Read Its Floor Plan", "unit_id": "trades-etf-2", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p2.vocabulary", "terms": [{"term": "survey", "tier": 3, "category": "measurement", "definition": "A recorded set of observations and measurements describing a site or work area.", "example": "Your survey includes a sketch, checked dimensions, and the positions of three features.", "order_index": 0, "difficulty": "medium"}, {"term": "datum", "tier": 3, "category": "measurement", "definition": "A chosen reference point, line, or surface from which measurements are taken.", "example": "Name corner A as the datum and locate three school-zone features from it.", "order_index": 1, "difficulty": "medium"}, {"term": "offset", "tier": 3, "category": "layout", "definition": "A stated distance and direction from a reference line or point to a feature.", "example": "Locate a fixture 12 in inward from the short end and state the reference edge.", "order_index": 2, "difficulty": "medium"}, {"term": "opening", "tier": 3, "category": "layout", "definition": "A gap in a surface, such as a window or door space, that must be accounted for in the design.", "example": "The model has a 12-ft² opening that is excluded from the wall covering estimate.", "order_index": 3, "difficulty": "medium"}, {"term": "plan view", "tier": 3, "category": "drawing", "definition": "A drawing showing a space or object as viewed from directly above.", "example": "Show the zone boundaries and equipment as seen from above.", "order_index": 4, "difficulty": "medium"}, {"term": "unit conversion", "tier": 2, "category": "math", "definition": "Expressing the same quantity in another unit without changing its size.", "example": "Convert 3 ft 4 in to 40 in before adding it to another length in inches.", "order_index": 5, "difficulty": "medium"}, {"term": "circulation", "tier": 3, "category": "layout", "definition": "The routes people use to move through a space.", "example": "Use the plan to keep the teacher-defined model walking route clear of equipment footprints.", "order_index": 6, "difficulty": "medium"}, {"term": "user need", "tier": 2, "category": "design", "definition": "A practical problem or requirement experienced by the person who will use the result.", "example": "Describe the actual difficulty the school user experiences before suggesting a storage solution.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "09594a2d-c603-5acf-89e8-21ef11952a74", "lesson_slug": "mvp-etf-2-04", "name": "ETF P2 · 04 · Turn the Floor Plan into a Scale Model", "unit_id": "trades-etf-2", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p2.vocabulary", "terms": [{"term": "scale", "tier": 3, "category": "drawing", "definition": "The stated relationship between a drawing length and the actual length it represents.", "example": "At 1 in = 2 ft, a 12-ft wall is drawn 6 in long.", "order_index": 0, "difficulty": "medium"}, {"term": "scale factor", "tier": 2, "category": "math", "definition": "The multiplier between corresponding lengths when both lengths use the same unit.", "example": "Because 2 ft = 24 in, the drawing-to-actual scale factor is 1/24.", "order_index": 1, "difficulty": "medium"}, {"term": "plan view", "tier": 3, "category": "drawing", "definition": "A drawing showing a space or object as viewed from directly above.", "example": "Show the zone boundaries and equipment as seen from above.", "order_index": 2, "difficulty": "medium"}, {"term": "elevation view", "tier": 3, "category": "drawing", "definition": "A drawing looking straight at a vertical face, showing heights and vertical relationships.", "example": "Show the selected divider height in a view of its vertical face.", "order_index": 3, "difficulty": "medium"}, {"term": "coordination", "tier": 2, "category": "design", "definition": "Checking that related drawings, dimensions, components, and routes work together without conflict.", "example": "Make sure the route order and positions agree in the plan, side view, and model.", "order_index": 4, "difficulty": "medium"}, {"term": "actual dimension", "tier": 3, "category": "measurement", "definition": "The full-size measurement of the real object or space, rather than its drawing size.", "example": "Label the real desk width as 2 ft even though its paper width is only 1 in.", "order_index": 5, "difficulty": "medium"}, {"term": "layout", "tier": 3, "category": "layout", "definition": "The planned or marked positions of parts, edges, and reference lines before making or placing something.", "example": "Lay out the work area's boundaries and fixture locations before placing the paper equipment.", "order_index": 6, "difficulty": "medium"}, {"term": "revision", "tier": 2, "category": "communication", "definition": "An identified change to a drawing, plan, or product that replaces an earlier version.", "example": "After checking an unclear endpoint, date the drawing and label the corrected version revision B.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "2f91683d-aeac-5a46-9296-1e2a91fa6b82", "lesson_slug": "mvp-etf-2-05", "name": "ETF P2 · 05 · Frame It and Brace It", "unit_id": "trades-etf-2", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p2.vocabulary", "terms": [{"term": "brace", "tier": 3, "category": "structures", "definition": "A member added to reduce unwanted movement or deformation of a structure.", "example": "Add a diagonal paper member to reduce the frame's sideways distortion.", "order_index": 0, "difficulty": "medium"}, {"term": "diagonal", "tier": 2, "category": "math", "definition": "A line segment joining two corners of a shape that are not next to each other.", "example": "Measure from one corner to the opposite corner, then check the other diagonal.", "order_index": 1, "difficulty": "medium"}, {"term": "Pythagorean theorem", "tier": 2, "category": "math", "definition": "For a right triangle, the square of the longest side equals the sum of the squares of the other two sides: c² = a² + b².", "example": "For the 36 × 48 in rectangle, the ideal diagonal is √(36² + 48²) = 60 in.", "order_index": 2, "difficulty": "medium"}, {"term": "racking", "tier": 3, "category": "structures", "definition": "A sideways distortion that changes the angles of a frame, such as a rectangle leaning into a parallelogram.", "example": "Observe how the unbraced rectangular frame changes into a slanted shape under sideways movement.", "order_index": 3, "difficulty": "medium"}, {"term": "triangulation", "tier": 3, "category": "structures", "definition": "Arranging members into triangles to resist changes of shape when the members and connections hold their lengths.", "example": "The diagonal divides the rectangular frame into triangles when its joints hold.", "order_index": 4, "difficulty": "medium"}, {"term": "joint", "tier": 3, "category": "fabrication", "definition": "The place and method by which two or more parts are connected.", "example": "Inspect the taped brace connections because a loose joint can let the frame move.", "order_index": 5, "difficulty": "medium"}, {"term": "load path", "tier": 3, "category": "structures", "definition": "The route by which forces pass through connected parts and supports.", "example": "Draw arrows showing how the applied load passes through the member to the supports.", "order_index": 6, "difficulty": "medium"}, {"term": "square (layout)", "tier": 3, "category": "layout", "definition": "Having the intended right angles; a rectangular layout must be checked against its side lengths and geometry.", "example": "Check side lengths and corner geometry before calling the work-area layout square; one correct diagonal is insufficient.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "56dbaefc-15bc-5d1d-a0bf-2cb04b4986d3", "lesson_slug": "mvp-etf-2-06", "name": "ETF P2 · 06 · Estimate and Install the Building Skin", "unit_id": "trades-etf-2", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p2.vocabulary", "terms": [{"term": "takeoff", "tier": 3, "category": "estimating", "definition": "Counting and measuring the material quantities needed from drawings or a surveyed job.", "example": "Use the wall drawing to list covering areas and the resulting sheet quantities.", "order_index": 0, "difficulty": "medium"}, {"term": "gross area", "tier": 3, "category": "math", "definition": "The full area before openings or other excluded areas are subtracted.", "example": "The supplied wall's full area is 96 ft² before subtracting the opening.", "order_index": 1, "difficulty": "medium"}, {"term": "net area", "tier": 3, "category": "math", "definition": "The area remaining after specified openings or excluded areas are subtracted from the gross area.", "example": "With no excluded openings, the 6 × 8 ft job needs 48 ft² of coverage.", "order_index": 2, "difficulty": "medium"}, {"term": "allowance", "tier": 3, "category": "layout", "definition": "An amount deliberately included for a stated purpose, such as overlap, cutting loss, or material thickness.", "example": "Include both 3/4-in wall allowances when recalculating each blank dimension.", "order_index": 3, "difficulty": "medium"}, {"term": "opening", "tier": 3, "category": "layout", "definition": "A gap in a surface, such as a window or door space, that must be accounted for in the design.", "example": "The model has a 12-ft² opening that is excluded from the wall covering estimate.", "order_index": 4, "difficulty": "medium"}, {"term": "cut list", "tier": 3, "category": "fabrication", "definition": "A list of the finished pieces to make, with each piece's size and quantity.", "example": "List two 6-ft border pieces and two 4-ft border pieces before deciding how much stock to buy.", "order_index": 5, "difficulty": "medium"}, {"term": "offcut", "tier": 3, "category": "fabrication", "definition": "A piece left after cutting that may still be usable for another part.", "example": "After four parts and four cuts, a 1/2-in piece of stock remains; decide whether it is useful.", "order_index": 6, "difficulty": "medium"}, {"term": "enclosure", "tier": 3, "category": "fabrication", "definition": "A surrounding structure that contains or protects parts of a system.", "example": "Build a paper base and four walls around the proposed low-voltage service route.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "cacdc7c7-c90f-5378-a594-a9e49f28cf85", "lesson_slug": "mvp-etf-2-07", "name": "ETF P2 · 07 · Test an Insulated Enclosure", "unit_id": "trades-etf-2", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p2.vocabulary", "terms": [{"term": "insulation", "tier": 3, "category": "thermal", "definition": "Material used to slow heat transfer through an assembly.", "example": "Compare a wrap intended to slow heat transfer with the reference arrangement.", "order_index": 0, "difficulty": "medium"}, {"term": "controlled variable", "tier": 2, "category": "investigation", "definition": "A condition deliberately kept the same to make a comparison fair.", "example": "Use the same paper allowance, support spacing, and loading method when comparing shapes.", "order_index": 1, "difficulty": "medium"}, {"term": "heat transfer", "tier": 3, "category": "thermal", "definition": "Energy moving from a warmer region to a cooler region because of a temperature difference.", "example": "The warmer cup transfers energy to its cooler surroundings during the comparison.", "order_index": 2, "difficulty": "medium"}, {"term": "baseline", "tier": 2, "category": "investigation", "definition": "The original or reference result used for comparison with a changed design or condition.", "example": "Use the original wrap's result as the comparison point for the revised design.", "order_index": 3, "difficulty": "medium"}, {"term": "percent reduction", "tier": 2, "category": "math", "definition": "The decrease divided by the original value, multiplied by 100%.", "example": "A drop reduced from 8°C to 6°C is 2/8 × 100% = 25% smaller than the original drop.", "order_index": 4, "difficulty": "medium"}, {"term": "thermal envelope", "tier": 3, "category": "thermal", "definition": "The parts of an enclosure that separate its inside from outside and affect heat transfer, such as walls, roof, and openings.", "example": "Identify the model wall and opening that separate the room's inside from its surroundings.", "order_index": 5, "difficulty": "medium"}, {"term": "trial", "tier": 2, "category": "investigation", "definition": "One run of a test using a recorded set of conditions.", "example": "Record each run and identify whether it used a fresh specimen or a previously loaded one.", "order_index": 6, "difficulty": "medium"}, {"term": "uncertainty", "tier": 2, "category": "measurement", "definition": "The doubt or range associated with a measurement because tools and methods cannot give an exact value.", "example": "Identify how reaction time or a hard-to-read volume mark affects confidence in the rate.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "be35d203-e56d-5279-9a65-eae23c5d528a", "lesson_slug": "mvp-etf-2-08", "name": "ETF P2 · 08 · Improve the Building and Its Envelope", "unit_id": "trades-etf-2", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p2.vocabulary", "terms": [{"term": "revision", "tier": 2, "category": "communication", "definition": "An identified change to a drawing, plan, or product that replaces an earlier version.", "example": "After checking an unclear endpoint, date the drawing and label the corrected version revision B.", "order_index": 0, "difficulty": "medium"}, {"term": "retest", "tier": 2, "category": "investigation", "definition": "A new test after a change, using stated conditions so the results can be compared.", "example": "Test the revised wrap under the original conditions and report an inconclusive result honestly if necessary.", "order_index": 1, "difficulty": "medium"}, {"term": "deflection", "tier": 3, "category": "structures", "definition": "The change in a part's position caused by loading, measured from its unloaded position.", "example": "A midspan height changing from 2 in to 1 3/4 in gives 1/4 in of downward deflection.", "order_index": 2, "difficulty": "medium"}, {"term": "percent reduction", "tier": 2, "category": "math", "definition": "The decrease divided by the original value, multiplied by 100%.", "example": "A drop reduced from 8°C to 6°C is 2/8 × 100% = 25% smaller than the original drop.", "order_index": 3, "difficulty": "medium"}, {"term": "thermal path", "tier": 3, "category": "thermal", "definition": "A route through which energy can transfer between warmer and cooler parts of a system.", "example": "Mark possible energy-transfer routes through the sides, lid, and base before changing one.", "order_index": 4, "difficulty": "medium"}, {"term": "inspection", "tier": 3, "category": "inspection", "definition": "A deliberate check of the work against its stated requirements.", "example": "Compare the completed model with every acceptance criterion in the plan.", "order_index": 5, "difficulty": "medium"}, {"term": "access", "tier": 3, "category": "design", "definition": "The space or opening needed to reach a part for operation, inspection, or maintenance.", "example": "Demonstrate that the chosen opening lets a person reach the model component without tearing the enclosure.", "order_index": 6, "difficulty": "medium"}, {"term": "evidence", "tier": 2, "category": "investigation", "definition": "Recorded observations, measurements, or results used to support a claim.", "example": "Record what you actually observed before choosing the next diagnostic action.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "c9138847-2637-52f2-842e-06bcf1884ff6", "lesson_slug": "mvp-etf-2-09", "name": "ETF P2 · 09 · Inspect and Demonstrate the Building", "unit_id": "trades-etf-2", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p2.vocabulary", "terms": [{"term": "inspection", "tier": 3, "category": "inspection", "definition": "A deliberate check of the work against its stated requirements.", "example": "Compare the completed model with every acceptance criterion in the plan.", "order_index": 0, "difficulty": "medium"}, {"term": "scale", "tier": 3, "category": "drawing", "definition": "The stated relationship between a drawing length and the actual length it represents.", "example": "At 1 in = 2 ft, a 12-ft wall is drawn 6 in long.", "order_index": 1, "difficulty": "medium"}, {"term": "offset", "tier": 3, "category": "layout", "definition": "A stated distance and direction from a reference line or point to a feature.", "example": "Locate a fixture 12 in inward from the short end and state the reference edge.", "order_index": 2, "difficulty": "medium"}, {"term": "acceptance criterion", "tier": 3, "category": "inspection", "definition": "A measurable requirement or stated test used to decide whether the work meets the job's needs.", "example": "One criterion is that a partner can locate both divider centers from your drawing without guessing.", "order_index": 3, "difficulty": "medium"}, {"term": "limitation", "tier": 2, "category": "investigation", "definition": "A boundary on what a method, model, or result can establish.", "example": "Explain which real-system tests were not performed on the paper prototype.", "order_index": 4, "difficulty": "medium"}, {"term": "handover", "tier": 3, "category": "communication", "definition": "The transfer of a completed work package and its essential information to the next person or user.", "example": "Give the next person the brief, drawings, estimate, test record, revisions, and unresolved questions.", "order_index": 5, "difficulty": "medium"}, {"term": "plan view", "tier": 3, "category": "drawing", "definition": "A drawing showing a space or object as viewed from directly above.", "example": "Show the zone boundaries and equipment as seen from above.", "order_index": 6, "difficulty": "medium"}, {"term": "measured value", "tier": 2, "category": "measurement", "definition": "A number with a unit obtained from a stated measurement method.", "example": "Record the actual tape reading of 40 3/8 in before judging whether it passes.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "e1bfd2e6-7789-5eb4-a6a2-44fadf241a58", "lesson_slug": "mvp-etf-2-10", "name": "ETF P2 · 10 · Workshop: Fix a Plan Conflict", "unit_id": "trades-etf-2", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p2.vocabulary", "terms": [{"term": "discrepancy", "tier": 2, "category": "inspection", "definition": "A difference between values or records that are expected to agree.", "example": "If the segment sum is 75 in but the direct measurement is 74 3/4 in, investigate the 1/4-in discrepancy.", "order_index": 0, "difficulty": "medium"}, {"term": "datum", "tier": 3, "category": "measurement", "definition": "A chosen reference point, line, or surface from which measurements are taken.", "example": "Name corner A as the datum and locate three school-zone features from it.", "order_index": 1, "difficulty": "medium"}, {"term": "coordination", "tier": 2, "category": "design", "definition": "Checking that related drawings, dimensions, components, and routes work together without conflict.", "example": "Make sure the route order and positions agree in the plan, side view, and model.", "order_index": 2, "difficulty": "medium"}, {"term": "elevation view", "tier": 3, "category": "drawing", "definition": "A drawing looking straight at a vertical face, showing heights and vertical relationships.", "example": "Show the selected divider height in a view of its vertical face.", "order_index": 3, "difficulty": "medium"}, {"term": "revision", "tier": 2, "category": "communication", "definition": "An identified change to a drawing, plan, or product that replaces an earlier version.", "example": "After checking an unclear endpoint, date the drawing and label the corrected version revision B.", "order_index": 4, "difficulty": "medium"}, {"term": "scale", "tier": 3, "category": "drawing", "definition": "The stated relationship between a drawing length and the actual length it represents.", "example": "At 1 in = 2 ft, a 12-ft wall is drawn 6 in long.", "order_index": 5, "difficulty": "medium"}, {"term": "offset", "tier": 3, "category": "layout", "definition": "A stated distance and direction from a reference line or point to a feature.", "example": "Locate a fixture 12 in inward from the short end and state the reference edge.", "order_index": 6, "difficulty": "medium"}, {"term": "verify", "tier": 2, "category": "inspection", "definition": "To check a claim, value, or condition against a measurement, calculation, or other evidence.", "example": "Check the new blank dimensions and test the revised fit before accepting the change.", "order_index": 7, "difficulty": "medium"}]}]$etf_data$::jsonb; item jsonb; saved jsonb; begin for item in select value from jsonb_array_elements(data) loop saved := public.save_lesson_vocabulary((item->>'lesson_id')::uuid,null,item->'terms',false); update public.vocabulary_sets set name=item->>'name',description=item->>'description',created_by='antoccic@fitchburg.k12.ma.us' where id=(saved->>'setId')::uuid; end loop; end $vocab$;
commit; select jsonb_build_object('project',2,'lessons',(select count(*) from lessons where unit_id='trades-etf-2' and not published),'vocabulary_sets',(select count(*) from vocabulary_sets where unit_id='trades-etf-2' and not published),'terms',(select count(*) from vocabulary_terms t join vocabulary_sets s on s.id=t.vocabulary_set_id where s.unit_id='trades-etf-2' and not t.archived));